class Solution {
    public IList<string> PermuteUnique(string s) {

        // Raj Thomas 12th May 2026 2:33AM IST
        bool[] isUsed = new bool[s.Length];
        IList<string> result = new List<string>();
        string item = "";

        // sort the string
        char[] arr = s.ToCharArray();
        Array.Sort(arr);
        s = new string(arr);

        Backtrack(s, item, result, isUsed);

        return result;
    }

    private IList<string> Backtrack(string s, string item, IList<string> result, bool[] isUsed) {

        if(item.Length == s.Length) {
            result.Add(new string(item));
            return result;
        }

        for(int i = 0; i < s.Length; i++) {

            if(isUsed[i] == true) continue;

            if(i > 0 && s[i] == s[i-1] && !isUsed[i -1]) continue;

            isUsed[i] = true;
            Backtrack(s, item + s[i], result, isUsed);

            isUsed[i] = false;
        }

        return result;
    }
}
